import{_ as o,C as a,o as s,c as r,j as e,a as l,E as d}from"./chunks/framework.QQy01QNh.js";const x=JSON.parse('{"title":"D.31　风险、灾害、公共卫生、指挥与恢复","description":"","frontmatter":{"title":"D.31　风险、灾害、公共卫生、指挥与恢复"},"headers":[],"relativePath":"theory/appendix-d/d-31.md","filePath":"theory/appendix-d/d-31.md"}'),i={name:"theory/appendix-d/d-31.md"};function c(p,t,u,m,h,f){const n=a("SectionLesson");return s(),r("div",null,[t[0]||(t[0]=e("div",{class:"theory-source"},[e("h1",{id:"section-d-31",tabindex:"-1"},[l("D.31　风险、灾害、公共卫生、指挥与恢复 "),e("a",{class:"header-anchor",href:"#section-d-31","aria-label":'Permalink to "D.31　风险、灾害、公共卫生、指挥与恢复 {#section-d-31}"'},"​")]),e("p",null,"正文连接：§6；§8.6；§12.6；§15.3.8；§16.13。研究入口：31.01—31.11。"),e("p",null,"危险源、暴露、脆弱性、观测、接受风险与采取行动不同。社会条件不能抹去洪水强度或病原，技术估计也不能独自决定谁应承担风险。预防应比较行动自身的伤害、比例、可行支持和复审，既不因不确定而无限扩权，也不等到完全确定才允许有限保护。"),e("p",null,"复杂耦合、可靠组织实践、潜伏防线、系统约束和正常任务适应，各有解释范围。保留核对的临时绕行与取消核对不同。是否保留核对，要看保护功能与任务关键区别是否仍受检验，而非格式是否相同；相称的替代核验须有专业依据。没有事故的证据价值依赖暴露与观测。事故之后真正建立了新流程，可以与安全净效果尚未确定、某一反馈介导学习分支尚未获支持三项并列。"),e("p",null,"临界减速只在相应动力学、噪声、采样与分岔条件下讨论，不能把任何波动当作将崩溃的信号。预警必须到达可理解、可调度且来得及完成保护的终端；警后无害可能是措施有效。感染、检测、确诊、报告与住院分母不同；信念变化、实际到检与健康后果不能互推。"),e("p",null,"医学分类、体验、病程、给付与治疗选择分别承担证据责任。共同决定可以改善知识，不自动保证长期健康。应急指挥交接、协调撤收、特别权限退出与生活恢复有不同的时钟。临时支持下真实恢复的功能不是假的，后来再受冲击也不必证明先前结论全错；只有超出已有证据的恢复声明才需要相应收窄。"),e("p",null,"预警提前量须覆盖核验、触达、理解、调度和保护起效所需时间。标签完整且目标已固定时，警后无事件仍可按该目标评分；行动避免了多少损害另需因果比较，离线监测不能填成零事件。临时供电或持续支持下功能恢复可以是真实恢复，评价须保留支持条件和实际覆盖人群，不能自动换成全部灾前用户。"),e("p",null,"专题定位：31.01 风险社会、预防与不确定性：Ulrich Beck 等；31.02 正常事故、高可靠组织：Perrow、Weick 等；31.03 偏差正常化与组织沉默：Diane Vaughan 等；31.04 灾害脆弱性、暴露与韧性；31.05 预警、临界减速与响应时钟；31.06 流行病、公共卫生与社会信任；31.07 医学化、精神卫生与健康决定因素；31.08 事故调查、问责与集体学习；31.09 医疗制度、临床伦理与共同决定；31.10 NIMS、ICS、应急指挥与功能降级；31.11 抢救、修复、重建与假恢复。")],-1)),d(n,{section:"D.31"}),t[1]||(t[1]=e("div",{class:"theory-source"},null,-1))])}const D=o(i,[["render",c]]);export{x as __pageData,D as default};
